import math
import sys

def main():
    input = sys.stdin.read().split()
    n = int(input[0])
    A = list(map(int, input[1:n+1]))

    prefix = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix[i] = math.gcd(prefix[i-1], A[i-1])

    suffix = [0] * (n + 2)
    for i in range(n-1, -1, -1):
        suffix[i] = math.gcd(A[i], suffix[i+1])

    max_gcd = 0
    for i in range(n):
        current = math.gcd(prefix[i], suffix[i+1])
        if current > max_gcd:
            max_gcd = current
    print(max_gcd)

